REVOKE UPDATE ON public.cultural_inspirations FROM authenticated;
GRANT UPDATE (category,title,photo_path,needs,backstory,steps,meaning,song_artist,song_url,reveal_on,feature_later) ON public.cultural_inspirations TO authenticated;
CREATE OR REPLACE FUNCTION trip_private.inspiration_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.trip_id<>OLD.trip_id OR NEW.creator_id<>OLD.creator_id OR NEW.partner_id IS DISTINCT FROM OLD.partner_id OR NEW.mode<>OLD.mode THEN RAISE EXCEPTION 'Experience ownership cannot be changed'; END IF; END IF; IF NEW.partner_id IS NOT NULL AND NOT trip_private.is_trip_member(NEW.trip_id,NEW.partner_id) THEN RAISE EXCEPTION 'Partner must be in the squad'; END IF; IF NEW.photo_path IS NOT NULL AND (split_part(NEW.photo_path,'/',1)<>NEW.id::text OR NEW.photo_path !~* '\.(jpe?g|png|webp)$') THEN RAISE EXCEPTION 'Invalid photo path'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;